from fractions import Fraction as F

def price_tree(spot,strike,up,down,gross,steps,kind,american):
    # Exact rational discrete model,no dividends;steps are periods,not calendar years.
    for value in (spot,strike,up,down,gross):
        if type(value) is not F or value<=0 or value>10000:
            raise ValueError('positive bounded Fraction required')
    if not down<gross<up:
        raise ValueError('strict no-arbitrage interval required')
    if type(steps) is not int or not 0<=steps<=16:
        raise ValueError('invalid bounded period count')
    if type(kind) is not str or kind not in ('call','put') or type(american) is not bool:
        raise ValueError('invalid exercise contract')
    p=(gross-down)/(up-down)
    def payoff(s):return max(F(0),s-strike if kind=='call' else strike-s)
    values=[payoff(spot*up**j*down**(steps-j)) for j in range(steps+1)]
    for level in range(steps-1,-1,-1):
        next_values=[]
        for j in range(level+1):
            continuation=((1-p)*values[j]+p*values[j+1])/gross
            immediate=payoff(spot*up**j*down**(level-j))
            next_values.append(max(immediate,continuation) if american else continuation)
        values=next_values
    return values[0]

args=(F(100),F(100),F(6,5),F(4,5),F(1))
print(price_tree(*args,1,'call',False))
print(price_tree(*args,2,'put',False))
print(price_tree(*args,2,'put',True))
print(price_tree(F(50),F(100),F(6,5),F(4,5),F(11,10),1,'put',False))
print(price_tree(F(50),F(100),F(6,5),F(4,5),F(11,10),1,'put',True))
